def elapsed_seconds(record, now):
    last_checked = record.last_accessed
    return (now - last_checked).total_seconds()

def remaining_days(today, deadline):
    diff = deadline - today
    return diff.days

def configure_schedule(settings):
    start = settings.first_run_date
    end = start + timedelta(days=7)
    return start, end

def await_release(clock, release_time):
    # Keep waiting until the release time arrives.
    while clock.now() < release_time:
        sleep(1)

